    "name": "INCLUDE/STDIO.H",
    "contents": "#ifndef __STDIO_H\n#define __STDIO_H\n\n#include <stddef.h>\n#include <stdarg.h>\n\n#define EOF (-1)\n#define BUFSIZ 512\n#define FILENAME_MAX 13          // MyDOS ã¯ 8.3 ã®ååã ãï¼é·ãååã»ãã£ã¬ã¯ããªä»ãã¯ libc ãç¸®ããï¼\n#define FOPEN_MAX 4              // MyDOS ãåæã«éãããã¡ã¤ã«ã®æ°\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n\n// MyDOS ã®ãã¡ã¤ã«ï¼libc/stdio.cï¼ãstdin ã¯ã­ã¼ãã¼ãï¼1 è¡ãã¤ï¼ãstdoutã»stderr ã¯ç»é¢\ntypedef struct __FILE {\n  int fd;                        // MyDOS ã®ãã³ãã«ã-1 = ç»é¢ã-2 = ã­ã¼ãã¼ã\n  int mode;                      // 'r' = èª­ãã'w' = æ¸ã\n  int eof, err;\n  int ungot;                     // ungetc ããæå­ï¼-1 = ãªãï¼\n  unsigned char *buf;            // BUFSIZ ãã¤ã\n  int pos, len;                  // èª­ãï¼buf ã®ä¸­ã®ä½ç½®ã¨é·ããæ¸ãï¼ãã¾ã£ãé·ãï¼posï¼\n  char **mbuf;                   // open_memstreamï¼ç¥ãããåï¼fd = -3ãbuf ã¯å¤§ãããã¦ãããlen ã¯ç¢ºä¿ããå¤§ããï¼\n  size_t *msize;\n} FILE;\n\nextern FILE *stdin, *stdout, *stderr;\n\nFILE *fopen(const char *name, const char *mode);\nFILE *open_memstream(char **bufp, size_t *sizep);\nint fclose(FILE *fp);\nsize_t fread(void *p, size_t size, size_t n, FILE *fp);\nsize_t fwrite(const void *p, size_t size, size_t n, FILE *fp);\nint fgetc(FILE *fp);\nint getc(FILE *fp);\nint fputc(int c, FILE *fp);\nint putc(int c, FILE *fp);\nchar *fgets(char *s, int n, FILE *fp);\nint fputs(const char *s, FILE *fp);\nint ungetc(int c, FILE *fp);\nint fflush(FILE *fp);\nint feof(FILE *fp);\nint ferror(FILE *fp);\nvoid clearerr(FILE *fp);\nint fseek(FILE *fp, long off, int whence);\nlong ftell(FILE *fp);\nvoid rewind(FILE *fp);\nint fileno(FILE *fp);\nint setvbuf(FILE *fp, char *buf, int mode, size_t size);\nint remove(const char *name);\nint rename(const char *from, const char *to);\nvoid perror(const char *s);\n\nint putchar(int c);\nint puts(const char *s);\nint getchar(void);\nint printf(const char *fmt, ...);\nint fprintf(FILE *fp, const char *fmt, ...);\nint sprintf(char *buf, const char *fmt, ...);\nint snprintf(char *buf, size_t n, const char *fmt, ...);\nint vprintf(const char *fmt, va_list ap);\nint vfprintf(FILE *fp, const char *fmt, va_list ap);\nint vsprintf(char *buf, const char *fmt, va_list ap);\nint vsnprintf(char *buf, size_t n, const char *fmt, va_list ap);\nint scanf(const char *fmt, ...);                // libc/scanf.c\nint fscanf(FILE *fp, const char *fmt, ...);\nint sscanf(const char *s, const char *fmt, ...);\nint vscanf(const char *fmt, va_list ap);\nint vfscanf(FILE *fp, const char *fmt, va_list ap);\nint vsscanf(const char *s, const char *fmt, va_list ap);\n\n#define _IOFBF 0\n#define _IOLBF 1\n#define _IONBF 2\n\n#endif\n"
